261	    public static long shiftCount(FValue y) {
262	        if (y instanceof FNN64) {
263	            long v = y.getNN64();
264	            return (v < 0) ? java.lang.Long.MAX_VALUE : v;
265	        }
266	        if (y instanceof FBigNum) {
267	            BigInteger b = y.getBigInteger();
268	            if (b.bitLength() < 64) return b.longValue();
269	            return (b.signum() < 0) ? java.lang.Long.MIN_VALUE : java.lang.Long.MAX_VALUE;
270	        }
271	        return y.getLong();
272	    }
