326	    public static long choose(long n, long k) {
327	        if (k > n / 2) k = n - k;
328	        if (k == 0) return 1;
329	        if (k == 1) return n;
330	        // k <= n/2
331	        // Will multiply (k) terms, n-k+1 through n-k+k
332	        // will divide by k terms, 1 through k
333	        // Note that if we divide after multiplying, it will
334	        // always be evenly divisible.
335	        // Proof: when we divide by k, we've multiplied by k consecutive integers,
336	        // at least one of which will be a multiple of k.
337	        long accum = 1;
338	        for (long j = 1; j <= k; j++) {
339	            long m = n - k + j;
340	            accum = accum * m;
341	            accum = accum / j;
342	        }
343	        return accum;
344	    }
345	
346	    public static long mod(long xi, long yi) {
347	        long ri = xi % yi;
348	        if (ri == 0) return 0;
349	
350	        if (yi > 0) {
351	            if (xi >= 0) return ri;
352	            return ri + yi;
353	        } else {
354	            if (xi >= 0) return ri + yi;
355	            return ri;
356	        }
357	    }
358	
359	    public static long pow(long x, long y) {
360	        long r = 1;
361	        while (y > 0) {
362	            if ((y & 1) != 0) {
363	                r *= x;
364	                y--;
365	            }
366	            x *= x;
367	            y >>>= 1;
368	        }
369	        return r;
370	    }
